<?php
declare(strict_types=1); require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../includes/functions.php'; require_login(); $error='';$categories=$pdo->query('SELECT category_id,category_name FROM categories ORDER BY category_name')->fetchAll();$organizers=$pdo->query('SELECT organizer_id,organizer_name FROM organizers ORDER BY organizer_name')->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';$id=filter_input(INPUT_POST,'event_id',FILTER_VALIDATE_INT);try{if($a==='save'){ $name=trim((string)($_POST['event_name']??''));$cat=filter_input(INPUT_POST,'category_id',FILTER_VALIDATE_INT);$org=filter_input(INPUT_POST,'organizer_id',FILTER_VALIDATE_INT);$date=$_POST['event_date']??'';$status=$_POST['status']??'Planned';if($name===''||!$cat||!$org||$date===''||!in_array($status,['Planned','Ongoing','Completed','Cancelled'],true))throw new InvalidArgumentException('Complete all required event fields.');$data=[$cat,$org,$name,trim((string)($_POST['description']??'')),$date,trim((string)($_POST['location']??'')),(float)($_POST['budget']??0),$status];if($id){$s=$pdo->prepare('UPDATE events SET category_id=?,organizer_id=?,event_name=?,description=?,event_date=?,location=?,budget=?,status=?,updated_at=NOW() WHERE event_id=?');$s->execute([...$data,$id]);flash('success','Event updated successfully.');}else{$s=$pdo->prepare('INSERT INTO events(category_id,organizer_id,event_name,description,event_date,location,budget,status) VALUES(?,?,?,?,?,?,?,?)');$s->execute($data);flash('success','Event added successfully.');}}elseif($a==='delete'&&$id){$s=$pdo->prepare('DELETE FROM events WHERE event_id=?');$s->execute([$id]);flash('success','Event deleted successfully.');}redirect('/event_shit/events/events.php');}catch(InvalidArgumentException|PDOException $x){$error=$x instanceof InvalidArgumentException?$x->getMessage():'Unable to complete the event operation.';}}$q=trim((string)($_GET['search']??''));$s=$pdo->prepare('SELECT e.*,c.category_name,o.organizer_name FROM events e LEFT JOIN categories c ON c.category_id=e.category_id LEFT JOIN organizers o ON o.organizer_id=e.organizer_id WHERE e.event_name LIKE ? OR e.location LIKE ? OR c.category_name LIKE ? OR o.organizer_name LIKE ? ORDER BY e.event_date DESC');$t="%$q%";$s->execute([$t,$t,$t,$t]);$rows=$s->fetchAll();$pageTitle='Events';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/sidebar.php';
?><main class="col-md-9 col-lg-10 p-4"><?php require __DIR__.'/../includes/alerts.php';if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="d-flex justify-content-between mb-4"><h1 class="h3">Events</h1><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#edit">+ Add event</button></div><form class="row g-2 mb-3"><div class="col-sm-6"><input class="form-control" name="search" value="<?=e($q)?>" placeholder="Search event, location, category, organizer"></div><div class="col-auto"><button class="btn btn-outline-secondary">Search</button></div></form><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Event</th><th>Category</th><th>Organizer</th><th>Date</th><th>Location</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['event_name'])?></td><td><?=e($r['category_name'])?></td><td><?=e($r['organizer_name'])?></td><td><?=e($r['event_date'])?></td><td><?=e($r['location'])?></td><td><span class="badge text-bg-light"><?=e($r['status'])?></span></td><td class="text-end"><button class="btn btn-sm btn-outline-primary" data-bs-toggle="modal" data-bs-target="#edit" data-id="<?=$r['event_id']?>" data-name="<?=e($r['event_name'])?>" data-category="<?=$r['category_id']?>" data-organizer="<?=$r['organizer_id']?>" data-description="<?=e($r['description'])?>" data-date="<?=$r['event_date']?>" data-location="<?=e($r['location'])?>" data-budget="<?=$r['budget']?>" data-status="<?=e($r['status'])?>">Edit</button><button class="btn btn-sm btn-outline-danger" data-bs-toggle="modal" data-bs-target="#delete" data-id="<?=$r['event_id']?>" data-name="<?=e($r['event_name'])?>">Delete</button></td></tr><?php endforeach;?></tbody></table></div></div></main><div class="modal fade" id="edit"><div class="modal-dialog modal-lg"><form class="modal-content" method="post"><div class="modal-header"><h2 class="modal-title fs-5">Event</h2><button class="btn-close" data-bs-dismiss="modal" type="button"></button></div><div class="modal-body"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="event_id" id="event_id"><div class="row g-3"><div class="col-md-6"><label class="form-label">Event name</label><input class="form-control" name="event_name" id="event_name" required></div><div class="col-md-3"><label class="form-label">Category</label><select class="form-select" name="category_id" id="category_id" required><?php foreach($categories as $c):?><option value="<?=$c['category_id']?>"><?=e($c['category_name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label class="form-label">Organizer</label><select class="form-select" name="organizer_id" id="organizer_id" required><?php foreach($organizers as $o):?><option value="<?=$o['organizer_id']?>"><?=e($o['organizer_name'])?></option><?php endforeach;?></select></div><div class="col-12"><label class="form-label">Description</label><textarea class="form-control" name="description" id="description"></textarea></div><div class="col-md-4"><label class="form-label">Date</label><input class="form-control" type="date" name="event_date" id="event_date" required></div><div class="col-md-4"><label class="form-label">Location</label><input class="form-control" name="location" id="location"></div><div class="col-md-2"><label class="form-label">Budget</label><input class="form-control" type="number" step="0.01" name="budget" id="budget"></div><div class="col-md-2"><label class="form-label">Status</label><select class="form-select" name="status" id="status"><?php foreach(['Planned','Ongoing','Completed','Cancelled'] as $st):?><option><?=$st?></option><?php endforeach;?></select></div></div></div><div class="modal-footer"><button class="btn btn-primary">Save</button></div></form></div></div><div class="modal fade" id="delete"><div class="modal-dialog"><form class="modal-content" method="post"><div class="modal-header"><h2 class="modal-title fs-5">Confirm delete</h2><button class="btn-close" data-bs-dismiss="modal" type="button"></button></div><div class="modal-body">Delete <strong id="dn"></strong>?<input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="event_id" id="di"></div><div class="modal-footer"><button class="btn btn-secondary" data-bs-dismiss="modal" type="button">Cancel</button><button class="btn btn-danger">Delete</button></div></form></div></div><script>edit.addEventListener('show.bs.modal',e=>{let b=e.relatedTarget;[['id','event_id'],['name','event_name'],['category','category_id'],['organizer','organizer_id'],['description','description'],['date','event_date'],['location','location'],['budget','budget'],['status','status']].forEach(x=>document.getElementById(x[1]).value=b.dataset[x[0]]||'')});delete.addEventListener('show.bs.modal',e=>{let b=e.relatedTarget;di.value=b.dataset.id;dn.textContent=b.dataset.name});</script><?php require __DIR__.'/../includes/footer.php';?>
